        "question": "P, Q, and R were partners in a firm. On 31st March 2023, after closing the accounts, it was discovered that interest on capital @ 6% p.a. as provided in the partnership deed was omitted. Their fixed capitals were: P ₹2,00,000; Q ₹1,50,000; and R ₹1,00,000. Profit-sharing ratio was 2:2:1. Pass the necessary adjustment journal entry showing your workings clearly. [3 Marks]",
        "answer": "Adjustment Entry: Q's Current A/c Dr. ₹1,800 to P's Current\nA/c ₹1,200 and R's Current A/c ₹600.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Calculate Interest Omitted:\nP = 6% on ₹2,00,000 = ₹12,000\nQ = 6% on ₹1,50,000 = ₹9,000\nR = 6% on ₹1,00,000 = ₹6,000\nTotal Interest to be credited = ₹27,000 \n[1 Mark]\n• 2. Adjustment Table:\n- Interest credited to partners: P +₹12,000; Q +₹9,000; R +₹6,000 (Total\n₹27,000)\n- Profit of ₹27,000 debited in 2:2:1: P -₹10,800; Q -₹10,800; R -₹5,400\n- Net effect: P = +₹1,200 (Cr.); Q = -₹1,800 (Dr.); R = +₹600 (Cr.) \n[1 Mark]\n• 3. Journal Entry \n[1 Mark] :\nQ's Current A/c Dr. ₹1,800\nTo P's Current A/c ₹1,200\nTo R's Current A/c ₹600\n(Adjustment entry passed for omission of interest on capital, fixed capital\nmethod)"
