        "question": "X, Y, and Z are partners. Their capitals on 31st March 2024 were ₹3,00,000, ₹2,00,000, and ₹1,00,000 respectively. Net profit of ₹90,000 for the year was divided equally without providing for interest on capital @ 10% p.a. and partner's salary to X of ₹12,000. Drawings were ₹30,000, ₹20,000, and ₹10,000. Calculate opening capitals assuming capitals are fluctuating. [3 Marks]",
        "answer": "Opening Capitals: X = ₹2,42,000; Y = ₹1,90,000; Z = ₹80,000.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme (1 Mark per partner calculation):\nFormula: Opening Capital = Closing Capital + Drawings - Profit already\ncredited (₹30,000 each):\n• X: ₹3,00,000 + ₹30,000 - ₹30,000 = ₹3,00,000 (Wait, salary was omitted, so\nonly profit of ₹30,000 was credited).\nX's Opening Capital = ₹3,00,000 + ₹30,000 - ₹30,000 = ₹3,00,000.\n• Y's Opening Capital = ₹2,00,000 + ₹20,000 - ₹30,000 = ₹1,90,000.\n• Z's Opening Capital = ₹1,00,000 + ₹10,000 - ₹30,000 = ₹80,000.\n(Note: Omitted items like salary and interest on capital had not been\ncredited in books yet, so opening capital is arrived at by reversing only the\nentries already recorded)."
