        "question": "Ramesh and Suresh are partners in a firm. Ramesh's drawings during 2023-24 were: 1st May 2023: ₹12,000; 31st July 2023: ₹6,000; 30th September 2023: ₹9,000; 30th November 2023: ₹12,000; 1st January 2024: ₹8,000; 31st March 2024: ₹7,000. Calculate interest on drawings @ 9% p.a. using the Product Method. [3 Marks]",
        "answer": "Total Product = ₹2,87,000; Interest on Drawings = ₹2,152.50.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Prepare Product Table \n[2 Marks] :\n- 01/05/2023: ₹12,000 × 11 months = ₹1,32,000\n- 31/07/2023: ₹6,000 × 8 months = ₹48,000\n- 30/09/2023: ₹9,000 × 6 months = ₹54,000\n- 30/11/2023: ₹12,000 × 4 months = ₹48,000\n- 01/01/2024: ₹8,000 × 3 months = ₹24,000\n- 31/03/2024: ₹7,000 × 0 months = ₹0\nTotal of Products = ₹3,06,000\n• 2. Calculate Interest \n[1 Mark] :\nInterest = Total of Products × Rate/100 × 1/12\nInterest = ₹3,06,000 × 9/100 × 1/12 = ₹2,295."
