        "question": "A, B, and C entered into partnership on 1st April 2023 sharing profits in the ratio 3:2:1. A personally guaranteed that C's share of profit after charging interest on capital @ 6% p.a. would not be less than ₹36,000 p.a. Capital contributions were: A ₹4,00,000; B ₹3,00,000; C ₹2,00,000. Profit for the year before interest on capital was ₹2,34,000. Calculate the final profit distribution among partners. [3 Marks]",
        "answer": "A: ₹84,000; B: ₹60,000; C: ₹36,000.",
