        "question": "Sajal and Kajal are partners sharing profits in the ratio 2:1. On 1st April 2023 their Capital Accounts showed balances of ₹5,00,000 and ₹4,00,000 respectively. Prepare Profit and Loss Appropriation Account and Partners' Capital Accounts for the year ended 31st March 2024 from the following information: (a) Interest on Capital is allowed @ 8% p.a. (b) Interest on Drawings is charged @ 6% p.a. Drawings were: Sajal ₹1,00,000 and Kajal ₹80,000. (c) Sajal is entitled to a salary of ₹4,000 per month and Kajal is entitled to a commission of 5% on net divisible profit after charging such commission. (d) The net profit for the year before any of the above adjustments was ₹3,84,600. [6 Marks]",
        "answer": "Net Divisible Profit = ₹2,52,000; Kajal's Commission =\n₹12,000; Profit Shares: Sajal ₹1,60,000, Kajal ₹80,000.\nCapital Balances: Sajal ₹6,62,000; Kajal ₹4,89,600.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n1. Profit and Loss Appropriation Account \n[3.5 Marks] :\n- Credit Side:\n* By Net Profit b/d = ₹3,84,600 \n[0.5 Mark]\n* By Interest on Drawings (average 6 months):\nSajal: ₹1,00,000 × 6/100 × 6/12 = ₹3,000\nKajal: ₹80,000 × 6/100 × 6/12 = ₹2,400\nTotal Interest on Drawings = ₹5,400 \n[1 Mark]\n* Total Credit = ₹3,90,000\n- Debit Side:\n* To Interest on Capital @ 8%:\nSajal: ₹40,000; Kajal: ₹32,000; Total = ₹72,000 \n[0.5 Mark]\n* To Sajal's Salary (₹4,000 × 12) = ₹48,000 \n[0.5 Mark]\n* Balance before commission = ₹3,90,000 - ₹1,20,000 = ₹2,70,000\n* To Kajal's Commission (5/105 × ₹2,70,000) = ₹12,857 (or if on net\ndivisible profit before commission: 5/100 × ₹2,52,000 = ₹12,000). Let's\n\ncompute: Profit before commission = ₹2,64,600 without drawings. With\ndrawings: ₹3,90,000 - ₹1,20,000 = ₹2,70,000. 5/105 × 2,70,000 = ₹12,857.\n[0.5 Mark]\n* Divisible Profit = ₹2,57,143 distributed in 2:1 -> Sajal ₹1,71,429; Kajal\n₹85,714. \n[0.5 Mark]\n2. Partners' Capital Accounts \n[2.5 Marks] :\n- Credit: Balance b/d, Interest on Capital, Salary, Commission, Share of\nProfit. \n[1.5 Marks]\n- Debit: Drawings, Interest on Drawings. \n[0.5 Mark]\n- Balance c/d correctly tallied. \n[0.5 Mark]"
