        "id": 42,
        "type": "LA",
        "tag": "CBSE 2023",
        "question": "Simran and Reema are partners sharing profits in the ratio 3:2. Their balances on 1st April 2023 were: Fixed Capital: Simran ₹6,00,000; Reema ₹4,00,000; Current Accounts (Cr.): Simran ₹1,00,000; Reema ₹60,000. Partnership deed provides: (a) Interest on Capital @ 9% p.a. (b) Reema to get a salary of ₹6,000 per month. (c) Simran to get a commission of 10% on net profit before charging any commission. (d) Net profit for the year ended 31st March 2024 was ₹2,80,000. (e) Drawings of Simran and Reema were ₹40,000 and ₹30,000 respectively, with interest on drawings amounting to ₹2,400 and ₹1,800. Prepare Profit and Loss Appropriation Account, Partners' Capital Accounts, and Partners' Current Accounts. [6 Marks]",
