        "question": "A and B are partners. Firm's average profit is ₹60,000 and Capital Employed is ₹4,00,000. Normal rate of return is 10%. If goodwill is valued at ₹80,000 by Super Profit Method, find the 'Number of Years of Purchase'. [3 Marks]",
