        "tag": "CBSE 2018",
        "question": "Why is Goodwill considered an intangible asset rather than a fictitious asset? Explain with two reasons. [3 Marks]",
        "answer": "Intangible asset because it has real commercial value and\naids profit generation, unlike fictitious assets.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1.5 Marks per point):\n• 1. Realisable Value: Goodwill has measurable market value and can be\nsold along with the enterprise, whereas fictitious assets (such as debit\nbalance of P&L or preliminary expenses) have zero realisable value.\n• 2. Profit Generation: Goodwill helps the business earn excess operating\nprofits over and above normal industry returns, whereas fictitious assets\ndo not contribute to revenue generation."
