        "question": "X and Y are partners sharing profits in the ratio 3:1. They admit Z as a partner on 1st April 2024 for 1/5th share. Z brings ₹1,00,000 as his capital and ₹30,000 as his share of premium for goodwill. Pass journal entries if: (a) Goodwill is retained in the business. (b) Half of the goodwill premium is withdrawn by the old partners. [3 Marks]",
