        "tag": "CBSE 2017",
        "question": "Why is it necessary to revalue assets and reassess liabilities upon the admission of a partner? [3 Marks]",
        "answer": "To record unrecorded values so that past gains/losses are\ngiven to old partners and incoming partner neither benefits\nnor suffers unjustly.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1 Mark per point):\n• 1. Real Present Values: Historical book values of assets and liabilities\nmay differ significantly from current realizable values.\n• 2. Fairness to Old Partners: Any unrecorded appreciation in assets earned\nin past years belongs solely to the old partners.\n• 3. Protection of New Partner: The incoming partner should not be\nburdened with unrecorded past losses or overstated asset values."
