        "question": "A and B were partners sharing profits in the ratio 3:2. On 1st April 2019, they admit C as a new partner. The terms of admission were: (a) C brings ₹50,000 as capital for 1/5th share and ₹15,000 for goodwill in cash. (b) Land and Building (book value ₹1,50,000) was appreciated by 20%. (c) Provision for doubtful debts was to be increased from ₹2,000 to ₹5,000. (d) An old customer whose account was written off as bad paid ₹3,000 in full settlement. (e) A liability of ₹4,000 for compensation to an ex-employee was to be recorded. Prepare Revaluation Account and Partners' Capital Accounts if opening capitals were A ₹2,00,000 and B ₹1,20,000. [6 Marks]",
