        "question": "A and B were partners sharing profits in the ratio 3:2. They admitted C into partnership for 1/5th share. C brought in ₹1,00,000 as capital and ₹30,000 as premium for goodwill. At the time of admission, the following appeared in their Balance Sheet: General Reserve: ₹50,000; Profit & Loss Account (Dr.): ₹20,000; Existing Goodwill: ₹25,000; Advertisement Suspense: ₹10,000. Pass all necessary journal entries to close and adjust the accumulated profits, losses, existing goodwill, and C's admission. [6 Marks]",
