        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme (1 Mark per journal entry):\n• 1. Distribute General Reserve (Old Ratio 3:2):\nGeneral Reserve A/c Dr. ₹50,000\nTo A's Capital A/c (3/5) ₹30,000\nTo B's Capital A/c (2/5) ₹20,000 \n[1 Mark]\n• 2. Write off Accumulated Loss (P&L Dr. Balance):\nA's Capital A/c (3/5) Dr. ₹12,000\nB's Capital A/c (2/5) Dr. ₹8,000\nTo Profit and Loss A/c ₹20,000 \n[1 Mark]\n• 3. Write off Existing Goodwill (Old Ratio 3:2):\nA's Capital A/c Dr. ₹15,000\nB's Capital A/c Dr. ₹10,000\nTo Goodwill A/c ₹25,000 \n[1 Mark]\n• 4. Write off Advertisement Suspense:\nA's Capital A/c Dr. ₹6,000\nB's Capital A/c Dr. ₹4,000\nTo Advertisement Suspense A/c ₹10,000 \n[1 Mark]\n• 5. Record C's Capital and Goodwill in Cash:\nBank A/c Dr. ₹1,30,000\nTo C's Capital A/c ₹1,00,000\nTo Premium for Goodwill A/c ₹30,000 \n[1 Mark]\n\n• 6. Distribute Goodwill Premium in Sacrificing Ratio (3:2):\nPremium for Goodwill A/c Dr. ₹30,000\nTo A's Capital A/c ₹18,000\nTo B's Capital A/c ₹12,000 \n[1 Mark]\nPART A: ACCOUNTING FOR PARTNERSHIP FIRMS\n50 Questions (Full Coverage)"
