        "type": "SA",
        "tag": "CBSE 2023",
        "question": "Ram, Mohan, and Sohan were partners in a firm sharing profits in the ratio 2:2:1. Sohan died on 30th June 2023. Sales for the year ended 31st March 2023 were ₹6,00,000 and profit was ₹1,20,000. Sales from 1st April 2023 to 30th June 2023 were ₹1,50,000. Calculate Sohan's share of profit up to date of death and pass the necessary journal entry. [3 Marks]",
