        "tag": "CBSE 2017",
        "question": "Explain the concept of 'Hidden Goodwill' on the retirement of a partner with a suitable numerical example. [3 Marks]",
        "answer": "Excess of agreed lump-sum settlement over adjusted capital\nrepresents hidden goodwill.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1.5 Marks for concept + 1.5 Marks for illustration):\n• 1. Concept: If the continuing partners agree to pay a lump-sum amount in\nexcess of what is strictly due on the basis of the retiring partner's capital\naccount after all revaluation and reserve adjustments, such excess is\ntreated as the retiring partner's share of Hidden Goodwill.\n• 2. Numerical Example: Suppose retiring partner C's adjusted capital is\n₹1,00,000, but partners agree to pay him ₹1,30,000 in full settlement. The\nexcess ₹30,000 is C's share of hidden goodwill, which will be debited to\ngaining partners in their gaining ratio."
