        "question": "A, B, and C were partners sharing profits in the ratio 2:2:1. C died on 30th June 2017. His capital on 31st March 2017 was ₹1,00,000. Under the partnership agreement, the executor was entitled to: (a) Interest on capital @ 12% p.a. (b) Share of profit up to date of death based on average profit of last 3 years (₹60,000). (c) Share of goodwill based on 2 years' purchase of average profit of last 3 years. (d) He had drawn ₹10,000 on 1st May 2017. Prepare C's Capital Account and explain the options available to his executor under Section 37 if the dues of ₹1,36,000 remain unpaid for 6 months while the firm earns ₹40,000 profit. [6 Marks]",
        "answer": "C's Capital transferred to Executor = ₹1,36,000; Under Sec\n37, Executor chooses between 6% interest (₹4,080) or\nproportionate profit share.",
