        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1 Mark per point):\n• 1. Continuation of Business: In dissolution of partnership, the business of\nthe firm continues under a reconstituted agreement. In dissolution of firm,\nthe business is permanently discontinued.\n• 2. Economic Relationship: In dissolution of partnership, the mutual\nrelationship between partners is modified. In dissolution of firm, the\nrelationship between all partners completely ends.\n• 3. Closure of Books: In dissolution of partnership, books of account\nremain open and assets/liabilities are revalued. In dissolution of firm, all\nbooks of account are permanently closed through the Realisation Account."
