        "question": "A and B were partners sharing profits equally. The firm was dissolved on 31st March 2018. A's Capital was ₹1,00,000 and B's Capital was ₹80,000. Creditors were ₹40,000. Cash balance was ₹10,000. The assets realized ₹1,80,000. Prepare the Realisation Account and determine profit or loss on realization. [3 Marks]",
        "answer": "Sundry Assets = ₹2,10,000; Loss on Realisation = ₹30,000\nshared equally (₹15,000 each).",
