        "question": "What is meant by an 'Unrecorded Asset' and an 'Unrecorded Liability'? How are they accounted for upon the dissolution of a partnership firm? [3 Marks]",
        "answer": "Assets/liabilities not shown in balance sheet; Cash realized\ncredited to Realisation A/c; Liabilities paid debited to\nRealisation A/c.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1.5 Marks each):\n• 1. Unrecorded Asset: An asset that was written off or omitted from the\nbalance sheet but has realizable value. When realized in cash: Cash A/c Dr.\nto Realisation A/c. When taken over by partner: Partner's Capital A/c Dr. to\nRealisation A/c.\n• 2. Unrecorded Liability: A liability or obligation not appearing in the\nbalance sheet that arises for settlement on dissolution. When paid in cash:\nRealisation A/c Dr. to Cash/Bank A/c. When undertaken by partner:\nRealisation A/c Dr. to Partner's Capital A/c."
