        "question": "Pass necessary journal entries on the dissolution of a partnership firm in the following cases: [6 Marks] (a) An unrecorded asset of ₹12,000 was taken over by partner X at ₹10,000. (b) Creditors of ₹60,000 accepted Plant and Machinery of book value ₹80,000 in full settlement. (c) Creditors of ₹90,000 accepted Stock of book value ₹70,000 at ₹65,000 and the remaining balance was paid to them in cash. (d) Loan of ₹30,000 advanced by partner Y was settled by paying him ₹28,000 in cash. (e) Realisation expenses of ₹4,000 were paid by partner Z from his personal pocket, which were to be borne by the firm. (f) An old typewriter which had been written off was sold for ₹3,500.",
        "answer": "(a) X's Capital Dr. ₹10,000 to Realisation; (b) No entry; (c)\nRealisation Dr. ₹25,000 to Bank; (d) Y's Loan Dr. ₹30,000 to\nBank (₹28,000) and Realisation (₹2,000); (e) Realisation Dr.\n₹4,000 to Z's Capital; (f) Bank Dr. ₹3,500 to Realisation.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme (1 Mark per journal entry):\n• (a) Asset taken over by X:\nX's Capital A/c Dr. ₹10,000\nTo Realisation A/c ₹10,000 \n[1 Mark]\n• (b) Asset accepted by creditors in full settlement:\nNo Journal Entry is required. \n[1 Mark]\n• (c) Creditors paid balance cash (₹90,000 - ₹65,000 = ₹25,000):\nRealisation A/c Dr. ₹25,000\nTo Bank A/c ₹25,000 \n[1 Mark]\n• (d) Settlement of partner's loan at discount:\nY's Loan A/c Dr. ₹30,000\nTo Bank A/c ₹28,000\nTo Realisation A/c ₹2,000 \n[1 Mark]\n• (e) Realisation expenses borne by firm, paid by Z:\nRealisation A/c Dr. ₹4,000\n\nTo Z's Capital A/c ₹4,000 \n[1 Mark]\n• (f) Scrap typewriter sold for cash:\nBank A/c Dr. ₹3,500\nTo Realisation A/c ₹3,500 \n[1 Mark]"
