        "answer": "Loss on Realisation = ₹60,000; Shilpa's Loan paid = ₹40,000;\nShilpa receives cash = ₹20,000; Meena brings in cash =\n₹14,000.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Realisation Account \n[2.5 Marks] :\n- Debit: Plant ₹2,00,000 + Stock ₹1,20,000 + Debtors ₹1,00,000 + Furniture\n₹50,000 + Bank (Creditors paid ₹95,000) + Bank (Expenses ₹5,000) =\n₹5,70,000.\n- Credit: Creditors ₹1,00,000 + Shilpa's Capital (Plant taken) ₹1,80,000 +\nMeena's Capital (Furniture ₹40,000 + Stock ₹1,00,000 = ₹1,40,000) + Bank\n(Debtors realized) ₹90,000 = ₹5,10,000.\n- Loss on Realisation = ₹5,70,000 - ₹5,10,000 = ₹60,000 distributed in 3:2\n(Shilpa ₹36,000; Meena ₹24,000). \n[1 Mark]\n• 2. Shilpa's Loan Account \n[0.5 Mark] :\n- Credit: Balance b/d ₹40,000.\n- Debit: To Bank A/c ₹40,000.\n• 3. Partners' Capital Accounts \n[1.5 Marks] :\n- Shilpa: Credit: ₹2,00,000 + Reserve (3/5 × 60,000 = ₹36,000) = ₹2,36,000.\n\nDebit: Plant ₹1,80,000 + Loss ₹36,000 = ₹2,16,000. Paid in cash = ₹20,000.\n[0.75 Mark]\n- Meena: Credit: ₹1,50,000 + Reserve ₹24,000 = ₹1,74,000. Debit: Assets\ntaken ₹1,40,000 + Loss ₹24,000 = ₹1,64,000. Paid in cash = ₹10,000 (Wait,\n₹1,74,000 - ₹1,64,000 = ₹10,000 paid). \n[0.75 Mark]\n• 4. Bank Account \n[1.5 Marks] :\n- Debits: Opening ₹80,000 + Debtors ₹90,000 = ₹1,70,000.\n- Credits: Creditors ₹95,000 + Expenses ₹5,000 + Shilpa's Loan ₹40,000 +\nShilpa paid ₹20,000 + Meena paid ₹10,000 = ₹1,70,000. (Tallied)."
