        "question": "Sunflag Ltd. invited applications for issuing 80,000 equity shares of ₹10 each at a premium of ₹2 per share. The amount was payable as follows: On Application: ₹3 per share On Allotment: ₹5 per share (including premium) On First and Final Call: Balance (₹4 per share) Applications were received for 1,20,000 shares. Allotment was made on pro-rata basis to all applicants. Excess application money was adjusted towards sums due on allotment. Mr. R, who had applied for 1,200 shares, failed to pay the allotment money and call money. His shares were forfeited after the call. Out of the forfeited shares, 600 shares were reissued as fully paid up for ₹9 per share. Pass necessary journal entries. [6 Marks]",
        "answer": "R allotted = 800 shares; Arrears on allotment = ₹2,800;\nAmount forfeited = ₹3,600; Capital Reserve = ₹2,100.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Calculate Allotment Ratio & R's Allotment \n[1 Mark] :\nRatio = 80,000 / 1,20,000 = 2/3.\nR applied = 1,200 shares. R allotted = 1,200 × 2/3 = 800 shares.\n• 2. Calculate R's Arrears on Allotment \n[1.5 Marks] :\nApplication money received from R = 1,200 × ₹3 = ₹3,600.\nApplication money required on allotted shares = 800 × ₹3 = ₹2,400.\nExcess application money adjusted to allotment = ₹1,200.\nAllotment money due from R = 800 × ₹5 = ₹4,000.\nCalls-in-Arrears on allotment = ₹4,000 - ₹1,200 = ₹2,800. \n[1 Mark]\n(Premium unpaid = 800 × ₹2 = ₹1,600; face value unpaid = ₹1,200).\n• 3. Journal Entry for Forfeiture \n[1.5 Marks] :\nShare Capital A/c (800 × ₹10) Dr. ₹8,000\nSecurities Premium A/c (800 × ₹2) Dr. ₹1,600\nTo Forfeited Shares A/c (Cash recd) ₹3,600\nTo Calls-in-Arrears A/c (₹2,800 + ₹3,200) ₹6,000 \n[1.5 Marks]\n• 4. Reissue Entry (600 shares @ ₹9 fully paid) \n[1 Mark] :\n\nBank A/c (600 × ₹9) Dr. ₹5,400\nForfeited Shares A/c (600 × ₹1) Dr. ₹600\nTo Share Capital A/c (600 × ₹10) ₹6,000\n• 5. Transfer to Capital Reserve \n[1 Mark] :\nForfeited amount on 600 shares = (₹3,600 / 800) × 600 = ₹2,700.\nLess discount on reissue = ₹600. Transfer = ₹2,700 - ₹600 = ₹2,100.\nForfeited Shares A/c Dr. ₹2,100\nTo Capital Reserve A/c ₹2,100"
