        "question": "Janta Ltd. invited applications for 50,000 equity shares of ₹10 each at a premium of ₹1 per share payable as: ₹3 on application, ₹4 on allotment (including premium), ₹2 on first call, and ₹2 on final call. Applications were received for 75,000 shares. Pro-rata allotment was made to all applicants: (a) Rohit, who was allotted 500 shares, failed to pay the allotment and call money. His shares were forfeited. (b) Mohit, who applied for 900 shares, failed to pay the two calls. His shares were also forfeited. All the forfeited shares of Rohit and Mohit were reissued as fully paid for ₹8 per share. Pass journal entries for forfeiture and reissue. [6 Marks]",
        "answer": "Rohit applied = 750 shares; Rohit arrears on allotment =\n₹1,250; Rohit forfeited amount = ₹2,250; Mohit allotted =\n600 shares; Mohit forfeited amount = ₹3,600; Capital\nReserve = ₹3,650.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Analysis of Rohit \n[2 Marks] :\nAllotment Ratio = 50,000 / 75,000 = 2/3.\nRohit allotted = 500 shares -> Applied = 500 × 3/2 = 750 shares.\nApplication money received = 750 × ₹3 = ₹2,250.\nApplication required = 500 × ₹3 = ₹1,500. Excess = ₹750.\nAllotment due = 500 × ₹4 = ₹2,000. Arrears on allotment = ₹2,000 - ₹750 =\n₹1,250.\n(Premium unpaid = ₹500; face value unpaid = ₹750).\nFirst Call unpaid = 500 × ₹2 = ₹1,000; Final Call = 500 × ₹2 = ₹1,000.\nForfeiture of Rohit's shares:\nShare Capital A/c (500 × ₹10) Dr. ₹5,000\nSecurities Premium A/c (500 × ₹1) Dr. ₹500\nTo Forfeited Shares A/c ₹2,250\nTo Calls-in-Arrears A/c (₹1,250 + ₹2,000) ₹3,250 \n[1 Mark]\n• 2. Analysis of Mohit \n[1.5 Marks] :\n\nMohit applied = 900 shares -> Allotted = 900 × 2/3 = 600 shares.\nMohit paid application and allotment (including premium). Premium is\nreceived and IGNORED.\nMohit failed to pay first call (600 × ₹2 = ₹1,200) and final call (600 × ₹2 =\n₹1,200).\nAmount paid = 600 × ₹6 = ₹3,600.\nForfeiture of Mohit's shares:\nShare Capital A/c (600 × ₹10) Dr. ₹6,000\nTo Forfeited Shares A/c ₹3,600\nTo Calls-in-Arrears A/c (600 × ₹4) ₹2,400 \n[1.5 Marks]\n• 3. Reissue of all 1,100 shares @ ₹8 fully paid \n[1.5 Marks] :\nBank A/c (1,100 × ₹8) Dr. ₹8,800\nForfeited Shares A/c (1,100 × ₹2) Dr. ₹2,200\nTo Share Capital A/c (1,100 × ₹10) ₹11,000 \n[1 Mark]\n• 4. Transfer to Capital Reserve \n[1 Mark] :\nTotal Forfeited Amount = ₹2,250 + ₹3,600 = ₹5,850.\nLess Reissue Discount = ₹2,200.\nTransfer = ₹5,850 - ₹2,200 = ₹3,650.\nForfeited Shares A/c Dr. ₹3,650\nTo Capital Reserve A/c ₹3,650"
