        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Analysis of Forfeiture \n[2.5 Marks] :\n- Called-up face value = ₹10 - ₹2 (uncalled final call) = ₹8 per share.\n- Premium of ₹2 per share was NOT received, hence debited.\n- Amount paid = Application ₹3 per share (400 × ₹3 = ₹1,200).\n- Amount unpaid = Allotment ₹5 + First call ₹2 = ₹7 per share (400 × ₹7 =\n₹2,800).\nJournal Entry:\nShare Capital A/c (400 × ₹8) Dr. ₹3,200 \n[1 Mark]\nSecurities Premium A/c (400 × ₹2) Dr. ₹800 \n[0.5 Mark]\nTo Forfeited Shares A/c ₹1,200 \n[0.5 Mark]\nTo Calls-in-Arrears A/c ₹2,800 \n[0.5 Mark]\n• 2. Reissue of 250 Shares \n[2 Marks] :\nReissued as ₹8 paid up for ₹7 per share -> Discount = ₹8 - ₹7 = ₹1 per\nshare.\nBank A/c (250 × ₹7) Dr. ₹1,750 \n[1 Mark]\nForfeited Shares A/c (250 × ₹1) Dr. ₹250 \n[0.5 Mark]\nTo Share Capital A/c (250 × ₹8) ₹2,000 \n[0.5 Mark]\n• 3. Transfer to Capital Reserve \n[1.5 Marks] :\nForfeited amount on 250 shares = 250 × ₹3 = ₹750.\nLess discount on reissue = ₹250.\nTransfer = ₹750 - ₹250 = ₹500.\n\nForfeited Shares A/c Dr. ₹500\nTo Capital Reserve A/c ₹500 \n[1.5 Marks]"
