        "tag": "CBSE 2020",
        "question": "A Ltd. purchased a running business from B Ltd. for a sum of ₹15,00,000 payable 10% in cash and the balance by the issue of equity shares of ₹10 each at a premium of 25%. The assets and liabilities of B Ltd. were: Plant ₹6,00,000; Land and Building ₹8,00,000; Stock ₹3,00,000; Sundry Debtors ₹2,00,000; Sundry Creditors ₹3,00,000; Bills Payable ₹1,00,000. Pass necessary journal entries in the books of A Ltd. [6 Marks]",
        "answer": "Net Assets = ₹15,00,000; Purchase consideration =\n₹15,00,000; Goodwill / Capital Reserve = Nil; Cash paid =\n₹1,50,000; Shares issued = 1,08,000 shares.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Calculate Net Assets \n[2 Marks] :\nTotal Assets = Plant ₹6,00,000 + Land ₹8,00,000 + Stock ₹3,00,000 +\nDebtors ₹2,00,000 = ₹19,00,000.\nOutside Liabilities = Creditors ₹3,00,000 + Bills Payable ₹1,00,000 =\n₹4,00,000.\nNet Assets = ₹19,00,000 - ₹4,00,000 = ₹15,00,000.\nPurchase Consideration = ₹15,00,000. (No Goodwill or Capital Reserve\narises).\n• 2. Journal Entry for Acquisition \n[2 Marks] :\nPlant and Machinery A/c Dr. ₹6,00,000\nLand and Building A/c Dr. ₹8,00,000\nStock A/c Dr. ₹3,00,000\nSundry Debtors A/c Dr. ₹2,00,000\nTo Sundry Creditors A/c ₹3,00,000\nTo Bills Payable A/c ₹1,00,000\nTo B Ltd. (Vendor) ₹15,00,000\n• 3. Settlement with Vendor \n[2 Marks] :\n- Cash paid = 10% of ₹15,00,000 = ₹1,50,000.\n- Balance consideration = ₹15,00,000 - ₹1,50,000 = ₹13,50,000.\n- Issue Price per share = ₹10 + 25% (₹2.50) = ₹12.50.\n- Number of shares = ₹13,50,000 / ₹12.50 = 1,08,000 shares.\nJournal Entry:\n\nB Ltd. Dr. ₹15,00,000\nTo Bank A/c ₹1,50,000\nTo Equity Share Capital A/c (1,08,000 × ₹10) ₹10,80,000\nTo Securities Premium A/c (1,08,000 × ₹2.50) ₹2,70,000"
