        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (0.75 Mark per point):\n• 1. Status: A shareholder is an owner/member of the company; a\ndebenture holder is a creditor/lender.\n• 2. Return on Investment: Return on shares is dividend, which is an\nappropriation of profit and fluctuates; return on debentures is interest,\nwhich is a fixed charge against profit.\n• 3. Voting Rights: Shareholders possess voting rights in general meetings;\ndebenture holders have no voting rights under Section 71.\n• 4. Repayment on Winding Up: Debentures are repaid prior to share capital\non liquidation; equity capital is repaid last."
