        "question": "A Ltd. issued 2,000 12% Debentures of ₹100 each at a discount of 5%, redeemable at a premium of 5%. The issue price was payable along with application. During the year, the company had ₹8,000 in Securities Premium Account. Pass all necessary journal entries for the issue of debentures, writing off the loss on issue, and payment of annual interest @ 12% assuming 10% TDS. [6 Marks]",
        "answer": "Loss on Issue = ₹20,000; Written off: Securities Premium\n₹8,000 + Statement of P&L ₹12,000; Annual Interest =\n₹24,000; TDS = ₹2,400.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Issue Entry \n[2 Marks] :\nTotal Loss = Discount (5% = ₹10,000) + Premium on redemption (5% =\n₹10,000) = ₹20,000.\nBank A/c (2,000 × ₹95) Dr. ₹1,90,000\nLoss on Issue of Debentures A/c Dr. ₹20,000\nTo 12% Debentures A/c (2,000 × ₹100) ₹2,00,000\nTo Premium on Redemption of Debentures ₹10,000\n• 2. Writing off Loss on Issue \n[2 Marks] :\nSecurities Premium available = ₹8,000.\nBalance charged to Statement of P&L = ₹20,000 - ₹8,000 = ₹12,000.\nSecurities Premium A/c Dr. ₹8,000\nStatement of Profit and Loss (Finance Costs) Dr. ₹12,000\nTo Loss on Issue of Debentures A/c ₹20,000\n• 3. Annual Interest and TDS \n[2 Marks] :\nAnnual Interest = 12% of ₹2,00,000 = ₹24,000. TDS = 10% = ₹2,400.\nDebenture Interest A/c Dr. ₹24,000\nTo Debentureholders A/c ₹21,600\nTo TDS Payable A/c ₹2,400\nPayments cleared: Bank credited ₹24,000.\nStatement of Profit and Loss Dr. ₹24,000 to Debenture Interest A/c\n₹24,000.\n\nPART B: FINANCIAL STATEMENT ANALYSIS\n50 Questions (Full Coverage)"
