        "answer": "Historical cost bias, Ignored qualitative elements, Personal\njudgment/estimates.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1 Mark each for any three):\n• 1. Historical Cost Basis: Financial statements record assets at historical\ncosts rather than current market replacement values, ignoring the impact\nof price-level changes and inflation.\n• 2. Ignores Qualitative Factors: Vital non-monetary aspects such as\nmanagement efficiency, industrial relations, customer loyalty, and brand\nperception are omitted.\n• 3. Subject to Personal Judgment & Estimates: Depreciation rates,\nprovisions for doubtful debts, and inventory valuations depend on\nestimates and subjective judgments of accountants."
