        "question": "What is meant by 'Financial Statements'? State any five primary objectives of preparing financial statements of a joint stock company. [6 Marks]",
        "answer": "Formal structured records; Objectives: Financial position,\nProfitability, Cash flows, Stewardship, Decision-making.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1 Mark for definition + 1 Mark each for 5 objectives):\n• Meaning: Financial statements are the structured end-products of the\nfinancial accounting process, comprising the Balance Sheet, Statement of\nProfit and Loss, Cash Flow Statement, and Notes to Accounts, presenting\nthe financial position and operating performance of an enterprise.\n• Objectives:\n1. Ascertaining Operating Performance: To present a true and fair view of\nthe operational profitability of the company.\n2. Ascertaining Financial Position: To report the accurate state of assets,\nliabilities, and owners' equity at the close of the financial year.\n3. Assessing Solvency and Liquidity: To assist lenders and suppliers in\nevaluating the firm's capacity to service debts and meet short-term\nobligations.\n4. Providing Useful Economic Data to Stakeholders: To assist investors,\ngovernment, employees, and analysts in making informed financial and\ninvestment decisions.\n5. Evaluating Management Stewardship: To judge how efficiently resources\nentrusted to directors have been utilized."
