        "answer": "Detailed explanatory schedules disclosing accounting\npolicies, breakdowns of line items, and contingent\ncommitments.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Significance of Notes to Accounts \n[2 Marks] :\nThe main Balance Sheet presents summarized figures for clarity and\nuncluttered layout. The Notes to Accounts are statutory, integral\nattachments that provide itemized breakdowns, reconciliations,\naccounting policies, and contingent disclosures necessary for a 'true and\nfair' view.\n• 2. Key Components [4 Marks (1 Mark each)]:\n(a) Significant Accounting Policies: Methods of depreciation, revenue\nrecognition, inventory valuation (AS-2), and foreign currency translations.\n(b) Detailed Breakdowns: Reconciliation of Share Capital (opening, shares\nissued, forfeited, closing), details of reserves, terms of long-term\nborrowings (rate of interest, repayment schedule).\n(c) Property, Plant and Equipment Schedule: Gross block, additions,\ndisposals, accumulated depreciation, and net carrying amounts.\n(d) Contingent Liabilities & Commitments: Claims against company not\nacknowledged as debts, bank guarantees, and capital contract\ncommitments."
