        "answer": "Distinction on Period, Nature, and Objective.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1 Mark per point):\n• 1. Period of Data: Horizontal analysis covers multiple years (time series).\nVertical analysis covers a single financial year or single balance sheet\ndate.\n• 2. Tools Used: Horizontal analysis uses Comparative Statements and\nTrend Percentages. Vertical analysis uses Common-Size Statements and\nFinancial Ratios.\n• 3. Purpose: Horizontal analysis reveals the growth trajectory and trends\nover time. Vertical analysis reveals the internal structural proportions and\ncost composition at a given point in time."
