        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1 Mark each for any three):\n• 1. Assessing Earning Capacity: Enables users to evaluate current\nprofitability and project future earnings potential.\n• 2. Assessing Solvency and Liquidity: Helps short-term and long-term\nlenders judge whether the business can meet its debts on time.\n• 3. Inter-firm and Intra-firm Comparisons: Facilitates benchmarking\nperformance against competitors and historical standards.\n• 4. Evaluating Managerial Efficiency: Evaluates how effectively managers\ndeploy capital and control operational costs."
