        "question": "The Current Ratio of a company is 2:1. State whether each of the following transactions will increase, decrease, or have no change on the ratio: [3 Marks] (a) Payment of Current Liability of ₹25,000. (b) Purchase of goods on credit for ₹40,000. (c) Sale of goods costing ₹20,000 for ₹25,000 cash.",
        "answer": "(a) Increase; (b) Decrease; (c) Increase.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme (1 Mark each):\n• (a) Payment of Current Liability: Decreases both Current Assets and\nCurrent Liabilities equally. Since initial ratio is 2:1 (>1:1), equal reduction\nincreases the ratio. \n[1 Mark]\n• (b) Purchase of goods on credit: Increases both Current Assets (Stock)\nand Current Liabilities (Creditors) equally. Equal increase when ratio >1:1\ndecreases the ratio. \n[1 Mark]\n• (c) Sale of goods costing ₹20,000 for ₹25,000 cash: Stock decreases by\n₹20,000 and Cash increases by ₹25,000 (Net increase in Current Assets = +\n₹5,000). Current Liabilities unchanged; hence ratio increases. \n[1 Mark]"
