        "question": "A firm has Net Profit after Tax of ₹2,40,000. Rate of Income Tax is 40%. The firm has 10% Debentures of ₹10,00,000. Calculate the 'Interest Coverage Ratio'. [3 Marks]",
        "answer": "NPBIT = ₹5,00,000; Interest = ₹1,00,000; Interest Coverage\nRatio = 5 Times.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Calculate Net Profit before Tax \n[1 Mark] :\nProfit before Tax = Net Profit after Tax / (1 - Tax rate) = ₹2,40,000 / 0.60 =\n₹4,00,000.\n• 2. Calculate Fixed Interest & NPBIT \n[1 Mark] :\nInterest on Debentures = 10% of ₹10,00,000 = ₹1,00,000.\nNet Profit before Interest & Tax (NPBIT) = ₹4,00,000 + ₹1,00,000 =\n₹5,00,000.\n• 3. Calculate Interest Coverage Ratio \n[1 Mark] :\nInterest Coverage Ratio = NPBIT / Interest = ₹5,00,000 / ₹1,00,000 = 5\nTimes."
