        "question": "Calculate 'Return on Investment (ROI)' from the following: [3 Marks] Net Profit after Tax: ₹1,20,000; Tax Rate: 40%; 12% Debentures: ₹5,00,000; Equity Share Capital: ₹6,00,000; Reserves & Surplus: ₹2,00,000.",
        "answer": "NPBIT = ₹2,60,000; Capital Employed = ₹13,00,000; ROI =\n20%.",
