        "answer": "Gross Profit Ratio = 40%; Operating Profit Ratio = 25%.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Gross Profit & GP Ratio \n[1.5 Marks] :\nGross Profit = ₹10,00,000 - ₹6,00,000 = ₹4,00,000.\nGross Profit Ratio = (₹4,00,000 / ₹10,00,000) × 100 = 40.0%.\n• 2. Operating Profit & Operating Profit Ratio \n[1.5 Marks] :\nOperating Profit = Gross Profit - Operating Expenses = ₹4,00,000 -\n₹1,50,000 = ₹2,50,000.\nOperating Profit Ratio = (₹2,50,000 / ₹10,00,000) × 100 = 25.0%."
