        "question": "What is meant by 'Liquidity Ratios'? Name the two primary liquidity ratios and explain their significance for a short-term creditor. [3 Marks]",
        "answer": "Ratios measuring ability to meet short-term debts; Current\nRatio and Quick Ratio.",
        "explanation": "Marking Scheme & Key Points:\nMarking Scheme (1 Mark for definition + 2 Marks for ratios & significance):\n• Definition: Liquidity ratios measure the ability of an enterprise to meet its\nmaturing short-term financial obligations promptly.\n• Ratios & Significance:\n1. Current Ratio (Current Assets / Current Liabilities): Measures overall\nbuffer of short-term resources available against current debts.\n2. Quick Ratio (Quick Assets / Current Liabilities): Tests immediate,\ninstantaneous cash-generating power without relying on future sales of\nstock."
