        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Calculate Current Liabilities \n[1 Mark] :\nQuick Ratio = Quick Assets / Current Liabilities\n1.5 = ₹1,50,000 / Current Liabilities -> Current Liabilities = ₹1,00,000.\n• 2. Calculate Current Assets \n[1 Mark] :\nCurrent Ratio = Current Assets / Current Liabilities\n2 = Current Assets / ₹1,00,000 -> Current Assets = ₹2,00,000.\n• 3. Calculate Inventory \n[1 Mark] :\nInventory = Current Assets - Quick Assets = ₹2,00,000 - ₹1,50,000 =\n₹50,000."
