        "question": "From the following details, calculate: [6 Marks] (a) Current Ratio (b) Quick Ratio (c) Debt-Equity Ratio (d) Working Capital Turnover Ratio Details: Revenue from Operations: ₹15,00,000 Cost of Revenue from Operations: ₹10,00,000 Share Capital: ₹6,00,000; Reserves and Surplus: ₹2,00,000 Non-Current Liabilities (10% Debentures): ₹4,00,000 Non-Current Assets: ₹9,00,000 Current Liabilities: ₹3,00,000; Inventories: ₹1,50,000.",
