        "answer": "Operating Cash Flow = +₹2,80,000; Investing Cash Flow = -\n₹3,20,000; Financing Cash Flow = +₹30,000; Net Decrease in\nCash = -₹10,000; Closing Cash = ₹40,000.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme:\n• 1. Operating Activities \n[2.5 Marks] :\nNet Profit before Tax = (₹2,50,000 - ₹1,50,000) + Proposed Div (₹40,000) =\n₹1,40,000\nAdd Depreciation: +₹70,000; Add Interest on Debentures: +₹30,000\nOperating Profit before WC = ₹2,40,000\nWC Changes: Inventories decr. (+₹20,000) + Payables incr. (+₹30,000) -\nReceivables incr. (-₹10,000) = +₹40,000\nNet Operating Cash Flow = ₹2,80,000.\n• 2. Investing Activities \n[1.5 Marks] :\nPPE purchases = Closing (₹9,50,000) + Dep (₹70,000) - Opening\n(₹7,00,000) = ₹3,20,000 (Outflow).\nNet Investing Cash Flow = -₹3,20,000.\n• 3. Financing Activities \n[1.5 Marks] :\nIssue of Shares: +₹2,00,000\n\nRedemption of Debentures: -₹1,00,000\nInterest paid: -₹30,000\nDividend paid: -₹40,000\nNet Financing Cash Flow = +₹30,000.\n• 4. Net Reconciliation \n[0.5 Mark] :\nNet Change = ₹2,80,000 - ₹3,20,000 + ₹30,000 = -₹10,000.\nOpening Cash ₹50,000 - ₹10,000 = Closing Cash ₹40,000."
