        "question": "What is the importance of a Cash Flow Statement to: [6 Marks] (a) Short-term creditors (b) Management for short-term financial planning (c) Investors evaluating dividend sustainability",
        "answer": "Vital insights into liquidity, cash budgeting, working capital\nmanagement, and dividend paying capability.",
        "explanation": "Marking Scheme & Key Points:\nStep-by-Step Marking Scheme (2 Marks each):\n• (a) Short-Term Creditors \n[2 Marks] :\nInterested in instantaneous cash generation. While the Statement of P&L\nmay show handsome accrued profits, a negative operating cash flow\nwarns creditors of impending liquidity failure and payment default.\n• (b) Enterprise Management \n[2 Marks] :\nProvides the empirical foundation for short-term financial planning and\ncash budgeting. Management identifies whether operational cash flows\nare adequate to finance routine working capital and capital expenditures\nwithout expensive short-term borrowing.\n• (c) Investors \n[2 Marks] :\nDividends cannot be paid out of accounting profits; they require hard cash.\nThe Cash Flow Statement reveals whether past dividends were covered by\nrobust operating cash flows or unsustainably funded by asset sales and\nfresh debts."
